from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from push_notifications.models import WebPushDevice

class WebPushDirectDispatchView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        device_id = request.data.get("device_id")
        alert_message = request.data.get("message", "Test Notification")

        # Enforce that caller can only send test alerts to their own registered devices
        device = WebPushDevice.objects.filter(
            id=device_id,
            user=request.user
        ).first()
        if not device:
            return Response({"error": "Target device not found or unauthorized"}, status=status.HTTP_404_NOT_FOUND)

        device.send_message(alert_message)
        return Response({"status": "Notification queued for device"}, status=status.HTTP_200_OK)
